    public async Task<Conversation?> GetConversationAsync(string owner,string id,CancellationToken token=default)
    {
        await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);
        await using var command=connection.CreateCommand();
        command.CommandText="SELECT title,state,model_profile_id,created_at,updated_at,version FROM conversations WHERE owner_principal_id=$owner AND conversation_id=$id AND state<>'DELETED';";
        command.Parameters.AddWithValue("$owner",owner);command.Parameters.AddWithValue("$id",id);
        await using var reader=await command.ExecuteReaderAsync(token).ConfigureAwait(false);
        return await reader.ReadAsync(token).ConfigureAwait(false)?new(owner,id,reader.GetString(0),reader.GetString(1),ReadNullableString(reader,2),ParseTimestamp(reader.GetString(3)),ParseTimestamp(reader.GetString(4)),reader.GetInt64(5)):null;
    }

    public async Task<Conversation?> UpdateConversationAsync(string owner,string id,string? title,string? state,long expectedVersion,CancellationToken token=default)
    {
        if(state is not null and not ("ACTIVE" or "ARCHIVED"))throw new ArgumentException("Conversation state is invalid.",nameof(state));
        await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);await using var command=connection.CreateCommand();
        command.CommandText="UPDATE conversations SET title=COALESCE($title,title),state=COALESCE($state,state),updated_at=$now,version=version+1 WHERE owner_principal_id=$owner AND conversation_id=$id AND version=$version AND state<>'DELETED';";
        command.Parameters.AddWithValue("$title",string.IsNullOrWhiteSpace(title)?DBNull.Value:title.Trim());command.Parameters.AddWithValue("$state",(object?)state??DBNull.Value);command.Parameters.AddWithValue("$now",FormatTimestamp(DateTimeOffset.UtcNow));command.Parameters.AddWithValue("$owner",owner);command.Parameters.AddWithValue("$id",id);command.Parameters.AddWithValue("$version",expectedVersion);
        if(await command.ExecuteNonQueryAsync(token).ConfigureAwait(false)!=1)return null;
        return await GetConversationAsync(owner,id,token).ConfigureAwait(false);
    }

