    public async Task<bool> AcceptChatExecutionAsync(ChatMessage userMessage,string executionId,string modelProfileId,string idempotencyKey,PublicExecutionEvent initialEvent,CancellationToken token=default)
    {
        await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);await using var transaction=(SqliteTransaction)await connection.BeginTransactionAsync(token).ConfigureAwait(false);
        await using(var message=connection.CreateCommand()){message.Transaction=transaction;message.CommandText="""
            INSERT OR IGNORE INTO messages(owner_principal_id,message_id,conversation_id,role,status,retry_of,created_at,completed_at,version)
            SELECT $owner,$id,$conversation,$role,$status,$retry,$created,$completed,$version
            FROM conversations WHERE owner_principal_id=$owner AND conversation_id=$conversation AND state='ACTIVE';
            """;message.Parameters.AddWithValue("$owner",userMessage.OwnerPrincipalId);message.Parameters.AddWithValue("$id",userMessage.MessageId);message.Parameters.AddWithValue("$conversation",userMessage.ConversationId);message.Parameters.AddWithValue("$role",userMessage.Role);message.Parameters.AddWithValue("$status",userMessage.Status);message.Parameters.AddWithValue("$retry",(object?)userMessage.RetryOf??DBNull.Value);message.Parameters.AddWithValue("$created",FormatTimestamp(userMessage.CreatedAt));message.Parameters.AddWithValue("$completed",userMessage.CompletedAt is null?DBNull.Value:FormatTimestamp(userMessage.CompletedAt.Value));message.Parameters.AddWithValue("$version",userMessage.Version);if(await message.ExecuteNonQueryAsync(token).ConfigureAwait(false)!=1){await transaction.RollbackAsync(token).ConfigureAwait(false);return false;}}
        foreach(var part in userMessage.Parts){await using var insert=connection.CreateCommand();insert.Transaction=transaction;insert.CommandText="INSERT INTO message_parts(owner_principal_id,part_id,message_id,sequence,kind,text,capability_call_id,capability_result_id,action_id,evidence_refs_json,error_code) VALUES($owner,$part,$message,$sequence,$kind,$text,$call,$result,$action,$evidence,$error);";insert.Parameters.AddWithValue("$owner",userMessage.OwnerPrincipalId);insert.Parameters.AddWithValue("$part",part.PartId);insert.Parameters.AddWithValue("$message",userMessage.MessageId);insert.Parameters.AddWithValue("$sequence",part.Sequence);insert.Parameters.AddWithValue("$kind",part.Kind);insert.Parameters.AddWithValue("$text",(object?)part.Text??DBNull.Value);insert.Parameters.AddWithValue("$call",(object?)part.CapabilityCallId??DBNull.Value);insert.Parameters.AddWithValue("$result",(object?)part.CapabilityResultId??DBNull.Value);insert.Parameters.AddWithValue("$action",(object?)part.ActionId??DBNull.Value);insert.Parameters.AddWithValue("$evidence",JsonSerializer.Serialize(part.EvidenceRefs??[]));insert.Parameters.AddWithValue("$error",(object?)part.ErrorCode??DBNull.Value);await insert.ExecuteNonQueryAsync(token).ConfigureAwait(false);}
        await using(var control=connection.CreateCommand()){control.Transaction=transaction;control.CommandText="INSERT INTO execution_controls(owner_principal_id,execution_id,conversation_id,message_id,state,updated_at,version,model_profile_id,idempotency_key) VALUES($owner,$execution,$conversation,$message,'RUNNING',$now,1,$profile,$key);";control.Parameters.AddWithValue("$owner",userMessage.OwnerPrincipalId);control.Parameters.AddWithValue("$execution",executionId);control.Parameters.AddWithValue("$conversation",userMessage.ConversationId);control.Parameters.AddWithValue("$message",userMessage.MessageId);control.Parameters.AddWithValue("$now",FormatTimestamp(userMessage.CreatedAt));control.Parameters.AddWithValue("$profile",modelProfileId);control.Parameters.AddWithValue("$key",idempotencyKey);await control.ExecuteNonQueryAsync(token).ConfigureAwait(false);}
        await using(var eventCommand=connection.CreateCommand()){eventCommand.Transaction=transaction;eventCommand.CommandText="INSERT INTO execution_events(owner_principal_id,event_id,execution_id,sequence,event_type,occurred_at,message_id,capability_call_id,action_id,data_json) VALUES($owner,$event,$execution,$sequence,$type,$at,$message,$call,$action,$data);";eventCommand.Parameters.AddWithValue("$owner",initialEvent.OwnerPrincipalId);eventCommand.Parameters.AddWithValue("$event",initialEvent.EventId);eventCommand.Parameters.AddWithValue("$execution",initialEvent.ExecutionId);eventCommand.Parameters.AddWithValue("$sequence",initialEvent.Sequence);eventCommand.Parameters.AddWithValue("$type",initialEvent.EventType);eventCommand.Parameters.AddWithValue("$at",FormatTimestamp(initialEvent.OccurredAt));eventCommand.Parameters.AddWithValue("$message",(object?)initialEvent.MessageId??DBNull.Value);eventCommand.Parameters.AddWithValue("$call",(object?)initialEvent.CapabilityCallId??DBNull.Value);eventCommand.Parameters.AddWithValue("$action",(object?)initialEvent.ActionId??DBNull.Value);eventCommand.Parameters.AddWithValue("$data",initialEvent.DataJson);await eventCommand.ExecuteNonQueryAsync(token).ConfigureAwait(false);}
        await transaction.CommitAsync(token).ConfigureAwait(false);return true;
    }

    public async Task<bool> AcceptChatRetryExecutionAsync(string owner,string conversationId,string userMessageId,string executionId,string modelProfileId,string idempotencyKey,PublicExecutionEvent initialEvent,CancellationToken token=default)
    {await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);await using var transaction=(SqliteTransaction)await connection.BeginTransactionAsync(token).ConfigureAwait(false);await using(var control=connection.CreateCommand()){control.Transaction=transaction;control.CommandText="""
        INSERT OR IGNORE INTO execution_controls(owner_principal_id,execution_id,conversation_id,message_id,state,updated_at,version,model_profile_id,idempotency_key)
        SELECT $owner,$execution,$conversation,$message,'RUNNING',$now,1,$profile,$key FROM messages
        WHERE owner_principal_id=$owner AND message_id=$message AND conversation_id=$conversation AND role='USER';
        """;control.Parameters.AddWithValue("$owner",owner);control.Parameters.AddWithValue("$execution",executionId);control.Parameters.AddWithValue("$conversation",conversationId);control.Parameters.AddWithValue("$message",userMessageId);control.Parameters.AddWithValue("$now",FormatTimestamp(initialEvent.OccurredAt));control.Parameters.AddWithValue("$profile",modelProfileId);control.Parameters.AddWithValue("$key",idempotencyKey);if(await control.ExecuteNonQueryAsync(token).ConfigureAwait(false)!=1){await transaction.RollbackAsync(token).ConfigureAwait(false);return false;}}await using(var eventCommand=connection.CreateCommand()){eventCommand.Transaction=transaction;eventCommand.CommandText="INSERT INTO execution_events(owner_principal_id,event_id,execution_id,sequence,event_type,occurred_at,message_id,capability_call_id,action_id,data_json) VALUES($owner,$event,$execution,$sequence,$type,$at,$message,NULL,NULL,$data);";eventCommand.Parameters.AddWithValue("$owner",owner);eventCommand.Parameters.AddWithValue("$event",initialEvent.EventId);eventCommand.Parameters.AddWithValue("$execution",executionId);eventCommand.Parameters.AddWithValue("$sequence",initialEvent.Sequence);eventCommand.Parameters.AddWithValue("$type",initialEvent.EventType);eventCommand.Parameters.AddWithValue("$at",FormatTimestamp(initialEvent.OccurredAt));eventCommand.Parameters.AddWithValue("$message",userMessageId);eventCommand.Parameters.AddWithValue("$data",initialEvent.DataJson);await eventCommand.ExecuteNonQueryAsync(token).ConfigureAwait(false);}await transaction.CommitAsync(token).ConfigureAwait(false);return true;}

