    public async Task<IReadOnlyList<PendingChatExecution>> ListPendingChatExecutionsAsync(CancellationToken token=default)
    {await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);await using var command=connection.CreateCommand();command.CommandText="""
        SELECT control.owner_principal_id,control.execution_id,control.conversation_id,control.message_id,part.text,control.model_profile_id,control.idempotency_key
        FROM execution_controls control
        JOIN conversations conversation ON conversation.owner_principal_id=control.owner_principal_id AND conversation.conversation_id=control.conversation_id
        JOIN message_parts part ON part.owner_principal_id=control.owner_principal_id AND part.message_id=control.message_id AND part.kind='TEXT'
        WHERE control.state='RUNNING' AND control.message_id IS NOT NULL AND control.model_profile_id IS NOT NULL AND control.idempotency_key IS NOT NULL
        ORDER BY control.updated_at,control.execution_id LIMIT 100;
        """;var values=new List<PendingChatExecution>();await using var reader=await command.ExecuteReaderAsync(token).ConfigureAwait(false);while(await reader.ReadAsync(token).ConfigureAwait(false))values.Add(new(reader.GetString(0),reader.GetString(1),reader.GetString(2),reader.GetString(3),reader.GetString(4),reader.GetString(5),reader.GetString(6)));return values.AsReadOnly();}

    public async Task<PluginInstallation?> GetPluginInstallationAsync(string owner,string id,string version,CancellationToken token=default)
        =>(await ListPluginInstallationsAsync(owner,token).ConfigureAwait(false)).SingleOrDefault(item=>item.PluginId==id&&item.PluginVersion==version);

    public async Task<PluginInstallation?> SetPluginConfigurationAsync(string owner,string id,string version,long expectedVersion,string configurationJson,CancellationToken token=default)
    {var installation=await GetPluginInstallationAsync(owner,id,version,token).ConfigureAwait(false);if(installation is null)return null;ValidateNonSecretConfiguration(configurationJson,ReadConfigurationFields(installation.ManifestJson));await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);await using var command=connection.CreateCommand();command.CommandText="UPDATE plugin_installations SET configuration_json=$configuration,updated_at=$now,version=version+1 WHERE owner_principal_id=$owner AND plugin_id=$id AND plugin_version=$pluginVersion AND version=$version AND removed=0;";command.Parameters.AddWithValue("$configuration",configurationJson);command.Parameters.AddWithValue("$now",FormatTimestamp(DateTimeOffset.UtcNow));command.Parameters.AddWithValue("$owner",owner);command.Parameters.AddWithValue("$id",id);command.Parameters.AddWithValue("$pluginVersion",version);command.Parameters.AddWithValue("$version",expectedVersion);if(await command.ExecuteNonQueryAsync(token).ConfigureAwait(false)!=1)return null;return await GetPluginInstallationAsync(owner,id,version,token).ConfigureAwait(false);}

    public async Task<string?> RemovePluginAsync(string owner,string id,string version,long expectedVersion,CancellationToken token=default)
    {
        var installation=await GetPluginInstallationAsync(owner,id,version,token).ConfigureAwait(false);if(installation is null)return "version_conflict";
        await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);
        await using(var guard=connection.CreateCommand())
        {guard.CommandText="""
            SELECT 1 WHERE EXISTS(SELECT 1 FROM connected_accounts WHERE owner_principal_id=$owner AND plugin_id=$id AND plugin_version=$pluginVersion AND lifecycle<>'REVOKED')
              OR EXISTS(SELECT 1 FROM durable_execution_requests WHERE owner_principal_id=$owner AND plugin_id=$id AND plugin_version=$pluginVersion)
              OR EXISTS(SELECT 1 FROM actions WHERE owner_principal_id=$owner AND plugin_id=$id AND plugin_version=$pluginVersion AND state IN ('PROPOSED','AUTHORIZED','STARTED','RECONCILIATION_REQUIRED'));
            """;guard.Parameters.AddWithValue("$owner",owner);guard.Parameters.AddWithValue("$id",id);guard.Parameters.AddWithValue("$pluginVersion",version);if(await guard.ExecuteScalarAsync(token).ConfigureAwait(false)is not null)return "plugin_in_use";}
        var capabilities=ReadManifestCapabilities(installation.ManifestJson);
        if(capabilities.Count>0)
        {await using var grants=connection.CreateCommand();grants.CommandText="SELECT c.capability_id,c.capability_version FROM job_capability_grants c JOIN jobs j ON j.owner_principal_id=c.owner_principal_id AND j.job_id=c.job_id WHERE c.owner_principal_id=$owner AND j.desired_state<>'CANCELED';";grants.Parameters.AddWithValue("$owner",owner);await using var reader=await grants.ExecuteReaderAsync(token).ConfigureAwait(false);while(await reader.ReadAsync(token).ConfigureAwait(false))if(capabilities.Contains((reader.GetString(0),reader.GetString(1))))return "plugin_in_use";}
        await using var command=connection.CreateCommand();command.CommandText="UPDATE plugin_installations SET enabled=0,removed=1,updated_at=$now,version=version+1 WHERE owner_principal_id=$owner AND plugin_id=$id AND plugin_version=$pluginVersion AND version=$version AND removed=0;";command.Parameters.AddWithValue("$now",FormatTimestamp(DateTimeOffset.UtcNow));command.Parameters.AddWithValue("$owner",owner);command.Parameters.AddWithValue("$id",id);command.Parameters.AddWithValue("$pluginVersion",version);command.Parameters.AddWithValue("$version",expectedVersion);return await command.ExecuteNonQueryAsync(token).ConfigureAwait(false)==1?null:"version_conflict";
    }

    public async Task<ActionRecord?> CancelActionAsync(string owner,string id,long expectedVersion,DateTimeOffset now,CancellationToken token=default)
    {var action=await GetActionAsync(owner,id,token).ConfigureAwait(false);if(action is null||action.Version!=expectedVersion||!ActionRecord.CanTransition(action.State,ActionState.Canceled))return null;var canceled=action.TransitionTo(ActionState.Canceled,now);return await UpdateAsync(owner,canceled,expectedVersion,token).ConfigureAwait(false)?canceled:null;}

    public async Task<ProductSettings> GetSettingsAsync(string owner,CancellationToken token=default)
    {await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);await using var command=connection.CreateCommand();command.CommandText="SELECT default_chat_model_profile_id,default_lightweight_model_profile_id,timezone,approval_defaults_json,memory_controls_json,version FROM product_settings WHERE owner_principal_id=$owner AND settings_id='default';";command.Parameters.AddWithValue("$owner",owner);await using var reader=await command.ExecuteReaderAsync(token).ConfigureAwait(false);return await reader.ReadAsync(token).ConfigureAwait(false)?new(owner,ReadNullableString(reader,0),ReadNullableString(reader,1),reader.GetString(2),reader.GetString(3),reader.GetString(4),reader.GetInt64(5)):new(owner,null,null,"UTC","{}","{}",1);}

    public async Task<ProductSettings?> UpdateSettingsAsync(string owner,string? chat,string? lightweight,string? timezone,string? approvals,string? memory,long expectedVersion,CancellationToken token=default)
    {
        _=TimeZoneInfo.FindSystemTimeZoneById(timezone??"UTC");
        foreach(var json in new[]{approvals,memory}.Where(value=>value is not null)){using var document=JsonDocument.Parse(json!);ProductContentValidation.Json(document.RootElement,"settings",16*1024);}
        if(chat is not null&&await GetModelProfileAsync(owner,chat,token).ConfigureAwait(false) is null)throw new ArgumentException("Default Chat model profile is invalid.",nameof(chat));
        if(lightweight is not null&&await GetModelProfileAsync(owner,lightweight,token).ConfigureAwait(false) is null)throw new ArgumentException("Default lightweight model profile is invalid.",nameof(lightweight));
        await using var connection=await OpenConnectionAsync(token).ConfigureAwait(false);await using var transaction=(SqliteTransaction)await connection.BeginTransactionAsync(token).ConfigureAwait(false);
        await using var command=connection.CreateCommand();command.Transaction=transaction;command.CommandText="""
            INSERT INTO product_settings(owner_principal_id,settings_id,default_chat_model_profile_id,default_lightweight_model_profile_id,timezone,approval_defaults_json,memory_controls_json,updated_at,version)
            SELECT $owner,'default',$chat,$lightweight,COALESCE($timezone,'UTC'),COALESCE($approvals,'{}'),COALESCE($memory,'{}'),$now,2 WHERE $expected=1 AND NOT EXISTS(SELECT 1 FROM product_settings WHERE owner_principal_id=$owner AND settings_id='default')
            ON CONFLICT(owner_principal_id,settings_id) DO UPDATE SET default_chat_model_profile_id=COALESCE($chat,default_chat_model_profile_id),default_lightweight_model_profile_id=COALESCE($lightweight,default_lightweight_model_profile_id),timezone=COALESCE($timezone,timezone),approval_defaults_json=COALESCE($approvals,approval_defaults_json),memory_controls_json=COALESCE($memory,memory_controls_json),updated_at=$now,version=product_settings.version+1 WHERE product_settings.version=$expected;
            """;command.Parameters.AddWithValue("$owner",owner);command.Parameters.AddWithValue("$chat",(object?)chat??DBNull.Value);command.Parameters.AddWithValue("$lightweight",(object?)lightweight??DBNull.Value);command.Parameters.AddWithValue("$timezone",(object?)timezone??DBNull.Value);command.Parameters.AddWithValue("$approvals",(object?)approvals??DBNull.Value);command.Parameters.AddWithValue("$memory",(object?)memory??DBNull.Value);command.Parameters.AddWithValue("$now",FormatTimestamp(DateTimeOffset.UtcNow));command.Parameters.AddWithValue("$expected",expectedVersion);if(await command.ExecuteNonQueryAsync(token).ConfigureAwait(false)!=1)return null;await transaction.CommitAsync(token).ConfigureAwait(false);return await GetSettingsAsync(owner,token).ConfigureAwait(false);
    }

